#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Read the generated AArch32 encoding table back from its C++ files.

The decoder's tables (darwin/cpu/arm64/aarch32/a32_encodings.{hpp,cpp}) are
generated by generate_a32_encoding_table.py. Tests and the inventory
validator that must not depend on the Arm XML or LLVM parse them here, check
their structure, and walk the decision trees as decode.cpp does.
"""

from __future__ import annotations

__import__("sys").dont_write_bytecode = True

import re
from pathlib import Path


REPOSITORY = Path(__file__).resolve().parents[3]
TABLE = REPOSITORY / "darwin/cpu/arm64/aarch32"
DATA = REPOSITORY / "tests/unit/arm64/aarch32_decoder"
THUMB32_FIRST = 0xE800
NO_PROGRAM = 65535
NO_COND = 255
STATUSES = {"ok", "nop", "undefined"}
REASONS = {"none", "unallocated", "unpredictable", "profile", "feature"}
ROW_KINDS = {"instruction", "unpredictable", "reserved_hint"}
ISAS = ("A32", "T16", "T32")


class TableError(ValueError):
    pass


def require(condition: bool, message: str) -> None:
    if not condition:
        raise TableError(message)


def read(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def count_constant(header: str, name: str) -> int:
    match = re.search(rf"\b{name}\s*=\s*(\d+);", header)
    require(match is not None, f"a32_encodings.hpp does not declare {name}")
    return int(match.group(1))


def array_body(source: str, name: str) -> str:
    match = re.search(rf"\b{name}\[[^\]]*\]\s*=\s*\{{\n(.*?)\n\}};", source, re.S)
    require(match is not None, f"a32_encodings.cpp does not define {name}")
    return match.group(1)


def number(text: str) -> int:
    return int(text.rstrip("uU"), 0)


class Tables:
    def __init__(self) -> None:
        header = read(TABLE / "a32_encodings.hpp")
        source = read(TABLE / "a32_encodings.cpp")
        for text, name in ((header, "a32_encodings.hpp"), (source, "a32_encodings.cpp")):
            require(text.startswith("// SPDX-License-Identifier: GPL-2.0-or-later\n"),
                    f"{name} lacks its SPDX header")
        self.counts = {
            name: count_constant(header, name)
            for name in (
                "kFormCount", "kRowCount", "kProgramCount", "kNodeCount",
                "kLeafRowCount", "kConstraintCount",
            )
        }
        self.header = header
        self.form_enum = self.parse_form_enum(header)
        self.forms = self.parse_forms(array_body(source, "kForms"))
        self.rows = self.parse_rows(array_body(source, "kRows"))
        self.constraints = self.parse_constraints(array_body(source, "kConstraints"))
        self.nodes = [
            tuple(int(v) for v in match)
            for match in re.findall(r"\{(-?\d+), (\d+), (\d+)\}", array_body(source, "kNodes"))
        ]
        self.leaf_rows = [int(v) for v in re.findall(r"\d+", array_body(source, "kLeafRows"))]
        roots = re.search(r"kTreeRoots\[3\]\s*=\s*\{(\d+), (\d+), (\d+)\};", source)
        require(roots is not None, "a32_encodings.cpp does not define kTreeRoots")
        self.roots = {isa: int(roots.group(i + 1)) for i, isa in enumerate(ISAS)}

    @staticmethod
    def parse_form_enum(header: str) -> list[str]:
        match = re.search(r"enum class Form : std::uint16_t \{\n(.*?)\n\};", header, re.S)
        require(match is not None, "a32_encodings.hpp does not declare Form")
        return [name.strip() for name in match.group(1).replace("\n", "").split(",") if name.strip()]

    @staticmethod
    def parse_forms(body: str) -> list[dict]:
        pattern = re.compile(
            r'\{"([^"]*)", "([^"]*)", (0x[0-9a-f]+u), (0x[0-9a-f]+u), (0x[0-9a-f]+u), '
            r"(\w+), ([\w: |]+), Isa::(\w+), Level::(\w+), Availability::(\w+), "
            r"Check::(\w+), (\w+), (\w+), (true|false), (true|false), (true|false)\},"
        )
        forms = []
        for line in body.split("\n"):
            match = pattern.fullmatch(line.strip())
            require(match is not None, f"unparsable form entry: {line[:80]}")
            (name, mnemonic, witness, should_mask, should_value, program, traits, isa,
             level, availability, check, feature, cond_low, conditional, nop,
             alu_exception_return) = match.groups()
            forms.append({
                "name": name,
                "mnemonic": mnemonic,
                "witness": number(witness),
                "should_mask": number(should_mask),
                "should_value": number(should_value),
                "program": NO_PROGRAM if program == "kNoProgram" else int(program),
                "traits": [t.strip().removeprefix("trait::") for t in traits.split("|")
                           if t.strip() != "0"],
                "feature": None if feature == "kNoFeature" else int(feature),
                "isa": isa,
                "level": level,
                "availability": availability,
                "check": check,
                "cond_low": NO_COND if cond_low == "kNoCond" else int(cond_low),
                "conditional": conditional == "true",
                "nop": nop == "true",
                "alu_exception_return": alu_exception_return == "true",
            })
        return forms

    @staticmethod
    def parse_rows(body: str) -> list[dict]:
        pattern = re.compile(
            r"\{(0x[0-9a-f]+u), (0x[0-9a-f]+u), (\d+), RowKind::(\w+), (\d+), (\d+)\},"
        )
        rows = []
        for line in body.split("\n"):
            match = pattern.fullmatch(line.strip())
            require(match is not None, f"unparsable row entry: {line[:80]}")
            mask, value, form, kind, count, first = match.groups()
            rows.append({
                "mask": number(mask),
                "value": number(value),
                "form": int(form),
                "kind": kind,
                "count": int(count),
                "first": int(first),
            })
        return rows

    @staticmethod
    def parse_constraints(body: str) -> list[dict]:
        pattern = re.compile(
            r"\{\{(\d+), (\d+), (\d+)\}, \{(\d+), (\d+), (\d+)\}, (true|false), "
            r"(0x[0-9a-f]+u), (0x[0-9a-f]+u)\},"
        )
        constraints = []
        for line in body.split("\n"):
            match = pattern.fullmatch(line.strip())
            require(match is not None, f"unparsable constraint entry: {line[:80]}")
            groups = match.groups()
            constraints.append({
                "low": [int(v) for v in groups[0:3]],
                "width": [int(v) for v in groups[3:6]],
                "negate": groups[6] == "true",
                "keep": number(groups[7]),
                "want": number(groups[8]),
            })
        return constraints

    def row_matches(self, row: dict, word: int) -> bool:
        if word & row["mask"] != row["value"]:
            return False
        for constraint in self.constraints[row["first"]:row["first"] + row["count"]]:
            value = 0
            for low, width in zip(constraint["low"], constraint["width"]):
                if width:
                    value = value << width | (word >> low & (1 << width) - 1)
            if ((value & constraint["keep"]) == constraint["want"]) == constraint["negate"]:
                return False
        return True

    def find(self, isa: str, word: int) -> dict | None:
        node = self.nodes[self.roots[isa]]
        while node[0] >= 0:
            node = self.nodes[node[2] if word >> node[0] & 1 else node[1]]
        for index in self.leaf_rows[node[1]:node[1] + node[2]]:
            row = self.rows[index]
            if self.row_matches(row, word):
                return row
        return None

    def form_of(self, isa: str, word: int) -> str:
        row = self.find(isa, word)
        return "Undefined" if row is None else self.forms[row["form"]]["name"]

    def check_structure(self) -> None:
        counts = self.counts
        require(len(self.forms) == counts["kFormCount"], "kFormCount differs from kForms")
        require(len(self.rows) == counts["kRowCount"], "kRowCount differs from kRows")
        require(len(self.nodes) == counts["kNodeCount"], "kNodeCount differs from kNodes")
        require(len(self.leaf_rows) == counts["kLeafRowCount"], "kLeafRowCount differs from kLeafRows")
        require(len(self.constraints) == counts["kConstraintCount"],
                "kConstraintCount differs from kConstraints")
        require(self.form_enum == [form["name"] for form in self.forms],
                "the Form enumeration and kForms differ")
        require(self.form_enum[:2] == ["Undefined", "ReservedHint"], "the pseudo-forms come first")
        require(len(set(self.form_enum)) == len(self.form_enum), "duplicate form name")
        programs = counts["kProgramCount"]
        for form in self.forms:
            require(form["program"] == NO_PROGRAM or form["program"] < programs,
                    f"{form['name']} names a program that does not exist")
            require(form["cond_low"] == NO_COND or form["cond_low"] == 28 or form["isa"] != "a32",
                    f"{form['name']} has an unexpected condition field position")
        for index, row in enumerate(self.rows):
            require(row["kind"] in ROW_KINDS, f"row {index} has kind {row['kind']}")
            require(row["form"] < len(self.forms), f"row {index} names a missing form")
            require(row["first"] + row["count"] <= len(self.constraints),
                    f"row {index} reads past the constraints")
            require(row["value"] & ~row["mask"] == 0, f"row {index} value is outside its mask")
        for index, constraint in enumerate(self.constraints):
            total = sum(constraint["width"])
            require(0 < total <= 16, f"constraint {index} is {total} bits wide")
            require(constraint["want"] & ~constraint["keep"] == 0,
                    f"constraint {index} wants a bit it does not keep")
            require(constraint["keep"] >> total == 0, f"constraint {index} keeps a bit past its fields")
            require(all(low + width <= 32 for low, width in
                        zip(constraint["low"], constraint["width"])),
                    f"constraint {index} reads past bit 31")
        for isa, root in self.roots.items():
            require(root < len(self.nodes), f"the {isa} tree root is out of range")
        for index, node in enumerate(self.nodes):
            bit, first, second = node
            if bit >= 0:
                require(bit < 32 and first < len(self.nodes) and second < len(self.nodes),
                        f"node {index} has an edge out of range")
                require(first != index and second != index, f"node {index} loops")
            else:
                require(first + second <= len(self.leaf_rows), f"leaf {index} reads past kLeafRows")
        require(all(row < len(self.rows) for row in self.leaf_rows), "a leaf names a missing row")
        # The trees are acyclic: a child precedes its parent.
        for index, (bit, first, second) in enumerate(self.nodes):
            if bit >= 0:
                require(first < index and second < index, f"node {index} has a forward edge")
